namespace kok {
 public class ManagedJob {public Job job;public string action,parentId;public Dictionary<string,object> args=new Dictionary<string,object>();public Dictionary<string,object> checkpoint=new Dictionary<string,object>();public bool stopping,pause;}
 internal sealed class JobRule {public string title,cancel;public bool resume;}
 internal static class JobRules {
  static readonly Dictionary<string,JobRule> rules=new Dictionary<string,JobRule>{
   {"importDropped",new JobRule{title="导入资料",resume=false}},
   {"importFiles",new JobRule{title="导入资料",resume=false}},
   {"importFolder",new JobRule{title="导入资料",resume=false}},
   {"importSamples",new JobRule{title="导入资料",resume=false}},
   {"translate",new JobRule{title="翻译",cancel="cancelTranslation",resume=true}},
   {"organizeFiles",new JobRule{title="AI 整理",cancel="cancelOrganization",resume=true}},
   {"scanSources",new JobRule{title="扫描文件夹",cancel="cancelSourceScan",resume=true}},
   {"generateSubtitles",new JobRule{title="生成字幕",cancel="cancelSpeech",resume=true}},
   {"installSpeech",new JobRule{title="准备语音组件",cancel="cancelSpeech",resume=true}},
   {"exportMediaEdit",new JobRule{title="导出媒体",cancel="cancelMediaEdit",resume=false}},
   {"chatWithFile",new JobRule{title="资料问答",cancel="cancelFileChat",resume=false}},
   {"runStudyTask",new JobRule{title="学习任务",cancel="cancelFileChat",resume=false}},
   {"runVisualEdit",new JobRule{title="AI 修改",cancel="cancelFileChat",resume=false}},
   {"runKnowledgeAnalysis",new JobRule{title="图谱分析",resume=false}},
   {"generateVideoOutline",new JobRule{title="视频大纲",resume=false}},
   {"recipeRun",new JobRule{title="运行配方",resume=true}},
   {"contentIndexBuild",new JobRule{title="Index source content",resume=true}},
   {"embeddingBuild",new JobRule{title="Build semantic index",resume=true}},
   {"indexLibrary",new JobRule{title="建立全文索引",resume=true}}
   ,{"summarizeContent",new JobRule{title="内容总结",resume=true}}
  };
  public static JobRule For(string action){JobRule rule;return rules.TryGetValue(action,out rule)?rule:null;}
 }
 public sealed partial class Jobs {
  readonly object gate=new object();readonly List<ManagedJob> managed=new List<ManagedJob>();readonly Dictionary<string,CancellationTokenSource> tokens=new Dictionary<string,CancellationTokenSource>();readonly AsyncLocal<string> scope=new AsyncLocal<string>();readonly AsyncLocal<CancellationToken> inheritedToken=new AsyncLocal<CancellationToken>();
  public async Task<object> WithCancellation(Func<Task<object>> run,CancellationToken token){var previous=inheritedToken.Value;inheritedToken.Value=token;try{return await run();}finally{inheritedToken.Value=previous;}}
  internal void Initialize(string dataDir){managedFilePath=Path.Combine(dataDir,"activity.sealed");if(File.Exists(managedFilePath)){try{var bytes=ProtectedData.Unprotect(File.ReadAllBytes(managedFilePath),Encoding.UTF8.GetBytes("kok.jobs.v1"),DataProtectionScope.CurrentUser);managed.AddRange(Library.Json.Deserialize<List<ManagedJob>>(Encoding.UTF8.GetString(bytes)));foreach(var row in managed.Where(r=>r.job.state=="running"||r.job.state=="queued")){row.job.state=row.job.resumable?"paused":"cancelled";row.stopping=false;row.pause=false;}}catch(Exception){loadProblem="活动记录无法读取，原记录已保留。";}}}
  string managedFilePath;
  string loadProblem;
  public void StopScope(string module=null){lock(gate){bool changed=false;foreach(var row in managed.Where(r=>r.job.state=="running"&&(module==null||r.job.module==module))){row.stopping=true;row.pause=row.job.resumable;CancellationTokenSource token;if(tokens.TryGetValue(row.job.id,out token))token.Cancel();changed=true;}if(changed)try{Persist();}catch(IOException){}}}
  void Persist(){var bytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(Library.Json.Serialize(managed)),Encoding.UTF8.GetBytes("kok.jobs.v1"),DataProtectionScope.CurrentUser);string temp=managedFilePath+".tmp";File.WriteAllBytes(temp,bytes);if(File.Exists(managedFilePath))File.Replace(temp,managedFilePath,managedFilePath+".bak");else File.Move(temp,managedFilePath);}
  public List<Job> ManagedSnapshot(){lock(gate){var rows=managed.Select(r=>Library.Json.Deserialize<Job>(Library.Json.Serialize(r.job))).ToList();if(loadProblem!=null)rows.Add(new Job{id="activity-unavailable",module="jobs",title=loadProblem,state="failed",detail="diagnostics",controllable=false,pausable=false});return rows;}}
  public CancellationToken CurrentToken{get{lock(gate){CancellationTokenSource token;return scope.Value!=null&&tokens.TryGetValue(scope.Value,out token)?token.Token:CancellationToken.None;}}}
  public string OperationKey(){if(scope.Value==null)return null;var point=Checkpoint();string step=point.ContainsKey("next")?Convert.ToString(point["next"]):"0";using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(scope.Value+"|"+step))).Replace("-","").Substring(0,32).ToLowerInvariant();}
  public void RequestCancellation(string action,Dictionary<string,object> args){lock(gate){foreach(var row in managed.Where(r=>r.job.state=="running"&&!r.stopping&&JobRules.For(r.action).cancel==action)){if(args.ContainsKey("jobId")&&(!row.args.ContainsKey("jobId")||Convert.ToString(row.args["jobId"])!=Convert.ToString(args["jobId"])))continue;row.stopping=true;row.pause=false;CancellationTokenSource token;if(tokens.TryGetValue(row.job.id,out token))token.Cancel();}if(loadProblem==null)try{Persist();}catch(IOException){}}}
  public Dictionary<string,object> Checkpoint(){lock(gate){var row=managed.FirstOrDefault(r=>r.job.id==scope.Value);return row==null?new Dictionary<string,object>():Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(row.checkpoint));}}
  public void RecordResult(object value){lock(gate){string id=scope.Value;while(id!=null){var row=managed.FirstOrDefault(r=>r.job.id==id);if(row==null)break;var entry=value as Entry;var op=value as Operation;var items=new List<string>();if(entry!=null){items.Add(entry.id);if(!String.IsNullOrEmpty(entry.agentOperationId))row.job.opIds=row.job.opIds.Concat(new[]{entry.agentOperationId}).Distinct().ToArray();}if(op!=null){row.job.opIds=row.job.opIds.Concat(new[]{op.id}).Distinct().ToArray();items.AddRange(op.patches.Select(p=>p.id));if(!String.IsNullOrEmpty(op.createdItemId))items.Add(op.createdItemId);items.AddRange(op.resources.Where(p=>p.kind=="item").Select(p=>p.id));}row.job.itemIds=row.job.itemIds.Concat(items).Distinct().ToArray();id=row.parentId;}}}
  void RecordOrigin(ModuleContext context,Dictionary<string,object> args){string operation=OperationOrigin.Id;if(operation==null||context.Library.OperationStatus(operation)!="applied")return;var result=new Operation{id=operation};string item=ModuleContext.Text(args,"id");if(context.Library.Find(item)!=null)result.patches.Add(new AgentChange{id=item});RecordResult(result);}
  public void Checkpoint(Dictionary<string,object> value){lock(gate){var row=managed.FirstOrDefault(r=>r.job.id==scope.Value);if(row!=null){row.checkpoint=value;Persist();}}}
  public async Task<object> RunAction(ModuleContext c,ActionSpec action,Dictionary<string,object> args){var rule=JobRules.For(action.Name);if(rule==null||c.Library.IsPrivate)return await action.Execute(c,args);if(loadProblem!=null)throw new InvalidDataException(loadProblem);ManagedJob row;CancellationTokenSource token;string previous=scope.Value;
   lock(gate){row=previous==null?null:managed.FirstOrDefault(r=>r.job.id==previous&&r.action==action.Name&&r.job.state=="paused");if(row==null){row=new ManagedJob{parentId=previous,action=action.Name,args=Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(args)),job=new Job{id="job:"+Guid.NewGuid().ToString("N"),module=action.Module,title=rule.title,state="queued",detail=action.Name,requires=action.Requires.Value,resumable=rule.resume,pausable=rule.resume}};managed.Add(row);}row.stopping=false;row.pause=false;row.job.state="running";CancellationTokenSource parent;token=previous!=null&&tokens.TryGetValue(previous,out parent)?CancellationTokenSource.CreateLinkedTokenSource(parent.Token):inheritedToken.Value.CanBeCanceled?CancellationTokenSource.CreateLinkedTokenSource(inheritedToken.Value):new CancellationTokenSource();tokens[row.job.id]=token;Persist();}scope.Value=row.job.id;Changed();
   try{object result=await action.Execute(c,args);RecordResult(result);RecordOrigin(c,args);token.Token.ThrowIfCancellationRequested();lock(gate){row.job.state="done";row.job.done=row.job.total>0?row.job.total:1;row.job.total=Math.Max(1,row.job.total);if(result is Entry)row.job.itemIds=row.job.itemIds.Concat(new[]{((Entry)result).id}).Distinct().ToArray();Persist();}notify("job.completed",new{id=row.job.id,items=row.job.itemIds,operations=row.job.opIds});return result;}
   catch(Exception){lock(gate){row.job.state=row.stopping?(row.pause?"paused":"cancelled"):token.IsCancellationRequested?"cancelled":"failed";Persist();}throw;}
   finally{lock(gate){tokens.Remove(row.job.id);token.Dispose();}scope.Value=previous;Changed();}
  }
  public async Task<object> Control(ModuleContext c,string id,string action){ManagedJob row;lock(gate){row=managed.FirstOrDefault(r=>r.job.id==id);if(row==null)throw new InvalidDataException("任务操作无效。");if(action=="resume"){if(!row.job.resumable||!new[]{"paused","failed"}.Contains(row.job.state))throw new InvalidDataException("任务操作无效。");row.job.state="paused";}else{if(new[]{"done","cancelled"}.Contains(row.job.state)||action=="pause"&&!row.job.pausable)throw new InvalidDataException("任务操作无效。");row.stopping=true;row.pause=action=="pause";CancellationTokenSource token;if(tokens.TryGetValue(id,out token))token.Cancel();else row.job.state=row.pause?"paused":"cancelled";Persist();}}
   if(action=="resume"){c.Policy.Ensure(row.job.requires,row.job.module);var previous=scope.Value;scope.Value=id;try{return await c.Invoke(row.action,row.args);}finally{scope.Value=previous;}}
   foreach(var child in ManagedSnapshot().Where(j=>managed.Any(r=>r.job.id==j.id&&r.parentId==id)&&new[]{"running","queued"}.Contains(j.state)).ToArray())await Control(c,child.id,action=="pause"&&child.pausable?"pause":"cancel");var rule=JobRules.For(row.action);if(rule.cancel!=null){var args=new Dictionary<string,object>();if(row.args.ContainsKey("jobId"))args["jobId"]=row.args["jobId"];await c.Invoke(rule.cancel,args);}Changed();return true;
  }
  public void Observe(string name,object data){if(data==null||!name.EndsWith("Progress",StringComparison.Ordinal)&&name!="sourceScan"&&name!="importing")return;var p=Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(data));lock(gate){foreach(var row in managed.Where(r=>r.job.state=="running")){object id;if(p.TryGetValue("jobId",out id)&&(!row.args.ContainsKey("jobId")||Convert.ToString(row.args["jobId"])!=Convert.ToString(id)))continue;if(!p.ContainsKey("jobId")&&!(name=="sourceScan"&&row.action=="scanSources"||name=="organizationProgress"&&row.action=="organizeFiles"||name=="importing"&&row.action.StartsWith("import",StringComparison.Ordinal)))continue;double done,total;if(p.ContainsKey("percent")&&Double.TryParse(Convert.ToString(p["percent"]),out done)){row.job.done=done;row.job.total=100;row.job.unit="percent";}else if(p.ContainsKey("total")&&Double.TryParse(Convert.ToString(p["total"]),out total)){row.job.total=total;row.job.done=p.ContainsKey("completed")?Convert.ToDouble(p["completed"]):p.ContainsKey("done")?Convert.ToDouble(p["done"]):0;row.job.unit="steps";}}}Changed();}
 }
 internal static class RecipeRunner {
  static object Resolve(object value,object previous){if(value is string&&((string)value).StartsWith("$previous.",StringComparison.Ordinal)){string key=((string)value).Substring(10);var row=Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(previous??new{}));object result;if(!row.TryGetValue(key,out result))throw new InvalidDataException("配方引用的上一步结果不存在。");return result;}var dictionary=value as Dictionary<string,object>;if(dictionary!=null)return dictionary.ToDictionary(p=>p.Key,p=>Resolve(p.Value,previous));var list=value as System.Collections.IEnumerable;if(list!=null&&!(value is string))return list.Cast<object>().Select(v=>Resolve(v,previous)).ToArray();return value;}
  public static async Task<object> Run(ModuleContext c,Dictionary<string,object> args){var id=ModuleContext.Text(args,"id");var workspace=(WorkspaceState)c.Library.WorkspaceSnapshot();var recipe=workspace.recipes.FirstOrDefault(r=>r.id==id);if(recipe==null)throw new InvalidDataException("配方内容无效。");var plan=RecipePlans.Preview(c,id);if(plan.problems.Count>0)throw new InvalidOperationException(String.Join("\n",plan.problems));if(args.ContainsKey("version")&&ModuleContext.Text(args,"version")!=plan.version)throw new InvalidOperationException("资料已变化，请重新预览。");string version=Library.Json.Serialize(recipe);var saved=c.Jobs.Checkpoint();if(saved.ContainsKey("version")&&Convert.ToString(saved["version"])!=version)throw new InvalidOperationException("配方已修改，请重新预览后运行。");int start=saved.ContainsKey("next")?Convert.ToInt32(saved["next"]):0;object previous=saved.ContainsKey("previous")?saved["previous"]:null;for(int n=start;n<recipe.steps.Count;n++){c.Jobs.CurrentToken.ThrowIfCancellationRequested();if(args.ContainsKey("version")&&RecipePlans.Preview(c,id).version!=ModuleContext.Text(args,"version"))throw new InvalidOperationException("资料已变化，请重新预览。");var step=recipe.steps[n];var cap=ModuleRegistry.Builtins.Capabilities.FirstOrDefault(a=>a.id==step.capability&&a.surfaces.Contains("recipe"));if(cap==null)throw new InvalidDataException("配方包含不可用能力。");c.Policy.Ensure(cap.requires,cap.module);var action=cap.actions.First(a=>a.UiCommand==null);var parameters=(Dictionary<string,object>)Resolve(step.args,previous);c.Jobs.Checkpoint(new Dictionary<string,object>{{"version",version},{"next",n},{"previous",previous}});using(OperationOrigin.Use("recipe:"+id,c.Jobs.OperationKey())){previous=await c.Invoke(action.Name,parameters);var operation=previous as Operation;if(operation!=null)previous=c.Ops.Apply(operation.id);c.Jobs.RecordResult(previous);}if(previous is Book)previous=new{text=String.Join("\n\n",((Book)previous).chapters.Select(ch=>ch.text)),title=((Book)previous).title};else if(previous is IEnumerable<SubtitleTrack>)previous=new{text=String.Join("\n",((IEnumerable<SubtitleTrack>)previous).Take(1).SelectMany(t=>t.cues).Select(c=>TimeSpan.FromSeconds(c.start).ToString(@"hh\:mm\:ss")+" "+c.text))};else if(previous is Entry){var item=(Entry)previous;previous=new{id=item.id,name=item.name,text=parameters.ContainsKey("text")?Convert.ToString(parameters["text"]):""};}c.Jobs.Checkpoint(new Dictionary<string,object>{{"version",version},{"next",n+1},{"previous",previous}});c.Notify("recipeProgress",new{completed=n+1,total=recipe.steps.Count});}return previous??new{done=true};}
 }
}
